const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const form=document.querySelector('[data-public-tool]');
if(form){const output=document.querySelector('#tool-result'),status=document.querySelector('#tool-status');try{const {runPublicTool}=await import('./public-tool-models.js?v=20261125-access01');const update=()=>{try{const d=Object.fromEntries([...form.querySelectorAll('[name]')].map(x=>[x.name,x.value.trim()===''?NaN:Number(x.value)])),r=runPublicTool(form.dataset.publicTool,d);output.innerHTML='<dl class="tool-stats">'+r.stats.map(([l,v])=>'<div><dt>'+esc(l)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'+(r.table?'<div class="table-scroll"><table><thead><tr>'+r.table.headers.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+r.table.rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'');status.textContent='结果已按当前输入更新。';status.removeAttribute('role');}catch(e){output.innerHTML='';status.textContent=e.message;status.setAttribute('role','alert');}};form.addEventListener('input',update);form.addEventListener('submit',e=>{e.preventDefault();update();});form.addEventListener('reset',()=>queueMicrotask(update));update();}catch{status.textContent='互动功能未能加载，请刷新页面；下方默认示例和计算方法仍可阅读。';status.setAttribute('role','alert');}}
